#include <iostream>
#include <numeric>
#include <algorithm>
using namespace std;

int main() {
    unsigned long long n, a, b, p, q;
    cin >> n >> a >> b >> p >> q;

    unsigned long long countA = n / a;
    unsigned long long countB = n / b;

    unsigned long long g = gcd(a, b);
    unsigned long long x = a / g;
    unsigned long long countBoth = (x > n / b) ? 0 : n / (x * b);

    __int128 total = static_cast<__int128>(countA) * p
                   + static_cast<__int128>(countB) * q
                   - static_cast<__int128>(countBoth) * min(p, q);

    if (total == 0) {
        cout << 0;
        return 0;
    }

    string result;
    while (total > 0) {
        result += static_cast<char>('0' + total % 10);
        total /= 10;
    }
    reverse(result.begin(), result.end());
    cout << result;

    return 0;
}

