    unsigned long long n, a, b, p, q;
    cin >> n >> a >> b >> p >> q;

    unsigned long long common = (n / a) / (b / gcd(a, b));
    unsigned long long total =
        (n / a) * p + (n / b) * q - common * min(p, q);

    cout << total << '\n';
    return 0;
}

