    if (value >= 10)
        print128(value / 10);
    cout << static_cast<char>('0' + value % 10);
}

int main() {
    unsigned long long n, a, b, p, q;
    cin >> n >> a >> b >> p >> q;

    unsigned long long commonDivisor = gcd(a, b);
    unsigned __int128 lcm =
        static_cast<unsigned __int128>(a / commonDivisor) * b;

    unsigned __int128 countA = n / a;
    unsigned __int128 countB = n / b;
    unsigned __int128 countBoth =
        lcm > n ? 0 : static_cast<unsigned __int128>(n) / lcm;

    unsigned __int128 total =
        countA * p + countB * q - countBoth * min(p, q);

    print128(total);
    cout << '\n';

    return 0;
}

#include <iostream>
#include <numeric>
#include <algorithm>
#include <string>
using namespace std;

int main() {
    unsigned long long n, a, b, p, q;
    cin >> n >> a >> b >> p >> q;

    unsigned long long countA = n / a;
    unsigned long long countB = n / b;

    __int128 lcm = static_cast<__int128>(a / gcd(a, b)) * b;
    unsigned long long countBoth =
        lcm > n ? 0 : n / static_cast<unsigned long long>(lcm);

    __int128 total =
        static_cast<__int128>(countA - countBoth) * p +
        static_cast<__int128>(countB - countBoth) * q +
        static_cast<__int128>(countBoth) * max(p, q);

    if (total == 0) {
        cout << 0;
        return 0;
    }

    string result;
    while (total > 0) {
        result.push_back('0' + total % 10);
        total /= 10;
    }
    reverse(result.begin(), result.end());

    cout << result << '\n';
    return 0;
}

